/* ServiceRequestMapper.findServiceRequestTitles */
SELECT SVC_REQ_SN, SVC_REQ_TTL
  FROM SERVICE_REQUEST
 WHERE SVC_REQ_USE_YN = 'Y'
   AND SVC_REQ_SN IN

    #{svcReqSn}

/* ServiceRequestMapper.searchServiceRequests */ SELECT s.SVC_REQ_SN, s.USR_SN, s.CAT_SN, s.SVC_REQ_FORM_TMPL_SN, c.CAT_NM, s.SVC_REQ_TTL, s.SVC_REQ_CN, s.SVC_REQ_BDGT_AMT, s.SVC_REQ_STATUS_CD, s.SVC_REQ_REG_DT, s.SVC_REQ_UPDT_DT FROM SERVICE_REQUEST s JOIN CATEGORY c ON c.CAT_SN = s.CAT_SN WHERE s.SVC_REQ_STATUS_CD = 'SVCC0002' AND s.SVC_REQ_USE_YN = 'Y'
AND (s.SVC_REQ_TTL LIKE CONCAT('%', #{keyword}, '%') OR s.SVC_REQ_CN LIKE CONCAT('%', #{keyword}, '%'))
AND s.CAT_SN = #{categorySn}
AND s.SVC_REQ_BDGT_AMT >= #{minBudget}
AND s.SVC_REQ_BDGT_AMT <= #{maxBudget}
ORDER BY
s.SVC_REQ_BDGT_AMT DESC, s.SVC_REQ_REG_DT DESC s.SVC_REQ_REG_DT DESC

mapper.update:
/* ServiceRequestMapper.updateServiceRequest */
UPDATE SERVICE_REQUEST
   SET CAT_SN            = #{catSn},
       SVC_REQ_FORM_TMPL_SN = #{formTemplateSn},
       SVC_REQ_TTL       = #{svcReqTtl},
       SVC_REQ_CN        = #{svcReqCn},
       SVC_REQ_BDGT_AMT  = #{svcReqBdgtAmt},
       SVC_REQ_STATUS_CD = #{svcReqStatusCd},
       SVC_REQ_UPDT_ID   = #{svcReqUpdtId}
 WHERE SVC_REQ_SN  = #{svcReqSn}
   AND USR_SN      = #{usrSn}
   AND SVC_REQ_STATUS_CD = 'SVCC0001'
   AND SVC_REQ_USE_YN = 'Y'

/* ServiceRequestMapper.closeServiceRequest */
UPDATE SERVICE_REQUEST
   SET SVC_REQ_STATUS_CD = 'SVCC0004',
       SVC_REQ_UPDT_ID   = #{updtId}
 WHERE SVC_REQ_SN = #{svcReqSn}
   AND USR_SN     = #{usrSn}
   AND SVC_REQ_STATUS_CD = 'SVCC0002'

