/* ServiceRequestMapper.findServiceRequestEntityById */
SELECT SVC_REQ_SN, USR_SN, CAT_SN, SVC_REQ_FORM_TMPL_SN, SVC_REQ_TTL, SVC_REQ_CN, SVC_REQ_BDGT_AMT, SVC_REQ_STATUS_CD,
       SVC_REQ_USE_YN, SVC_REQ_REG_DT, SVC_REQ_UPDT_DT, SVC_REQ_REG_ID, SVC_REQ_UPDT_ID
  FROM SERVICE_REQUEST
 WHERE SVC_REQ_SN = #{svcReqSn}

/* ServiceRequestMapper.findServiceRequestEntityByIdForUpdate */
SELECT SVC_REQ_SN, USR_SN, CAT_SN, SVC_REQ_FORM_TMPL_SN, SVC_REQ_TTL, SVC_REQ_CN, SVC_REQ_BDGT_AMT, SVC_REQ_STATUS_CD,
       SVC_REQ_USE_YN, SVC_REQ_REG_DT, SVC_REQ_UPDT_DT, SVC_REQ_REG_ID, SVC_REQ_UPDT_ID
  FROM SERVICE_REQUEST
 WHERE SVC_REQ_SN = #{svcReqSn}
 FOR UPDATE

